import json,glob,os,sys
res={}
for f in glob.glob('export/*.ndjson'):
    t=os.path.basename(f)[:-7]
    res[t]=[json.loads(l) for l in open(f)]
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r):
    return ext(r,'event-time') or r.get('date') or ''
def subj(r):
    for k in ('subject','patient'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in res['Patient']}
eps={}
for e in res['EpisodeOfCare']: eps.setdefault(subj(e),[]).append(e)
byp={}
for t,rs in res.items():
    if t in ('Patient','EpisodeOfCare'): continue
    for r in rs:
        byp.setdefault(subj(r),[]).append(r)
