cd /tmp && cat > summ.py <<'EOF'
import json,glob,os,sys
res={}
for f in glob.glob('export/*.ndjson'):
    t=os.path.basename(f)[:-7]
    res[t]=[json.loads(l) for l in open(f)]
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time') or r.get('date') or ''
def subj(r):
    for k in ('subject','patient'):
        if k in r and 'reference' in r[k]: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in res['Patient']}
acc={}
for b in res['Basic']:
    acc.setdefault(ext(b,'accession'),[]).append(b)
spec={s['id']:s for s in res['Specimen']}

def fmt(r):
    t=r['resourceType']; i=r['id']; e=et(r)
    o=f"[{e}] {t}/{i}: "
    if t=='EpisodeOfCare': o+=f"EPISODE start={r['period']['start']} {r['type'][0]['text']}"
    elif t=='Condition': o+=f"DX '{r['code']['text']}' recorded={r.get('recordedDate')} by {r.get('recorder',{}).get('display')}"
    elif t=='Observation':
        o+=f"OBS '{r['code']['text']}' status={r['status']} collected={r.get('effectiveDateTime')} issued={r.get('issued')} value={r.get('valueString')!r} accession={r.get('identifier',[{}])[0].get('value')} specimen={r.get('specimen',{}).get('reference','')}"
        if r.get('note'): o+=" NOTE:"+ " | ".join(n['text'] for n in r['note'])
    elif t=='Specimen':
        o+=f"SPEC acc={r['accessionIdentifier']['value']} collected={r['collection'].get('collectedDateTime')} by {r['collection'].get('collector',{}).get('display')} label_name={ext(r,'label-name')} label_mrn={ext(r,'label-mrn')} label_dob={ext(r,'label-dob')}"
    elif t=='MedicationAdministration':
        o+=f"MEDADMIN {r['medicationCodeableConcept']['text']} status={r['status']} {r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} by {r.get('performer',[{}])[0].get('actor',{}).get('display')}"
        if r.get('note'): o+=" NOTE:"+" | ".join(n['text'] for n in r['note'])
        if r.get('statusReason'): o+=f" statusReason={r['statusReason']}"
    elif t=='MedicationDispense':
        o+=f"DISPENSE {r['medicationCodeableConcept']['text']} qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handedOver={r.get('whenHandedOver')} instr={[d.get('text') for d in r.get('dosageInstruction',[])]}"
