    return (t['id'],t['for']['reference'],t['focus']['reference'],t['code']['coding'][0]['code'],t['businessStatus']['coding'][0]['code'] if isinstance(t['businessStatus'],dict) else t['businessStatus'],me,len(ev),len(t['description']) if 'description' in t else len(t.get('note',[{}])[0].get('text','')))
for t in its: print(g(t))
